def has_connected_neighbor(r, c, grid, val):
    """Check if cell (r,c) with value val has any 4-connected neighbor of same value"""
    rows, cols = len(grid), len(grid[0])
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == val:
            return True
    return False

